SELECT id, customer_id, account_type, balance, opened_date, status, LAST_VALUE(status) IGNORE NULLS OVER (ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_status, NTILE(4) OVER (PARTITION BY customer_id, status ORDER BY balance, id) AS balance_bucket, ROW_NUMBER() OVER (PARTITION BY status ORDER BY balance, id) AS event_seq, LEAD(balance, 1) OVER (PARTITION BY account_type, customer_id ORDER BY balance, id) AS next_balance, SUM(balance) OVER (ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_balance FROM accounts;
